def round_half_to_even(n: float) -> int:
    """Rounds a floating-point number to the nearest integer, rounding half to even.

    Args:
        n (float): The number to be rounded.

    Returns:
        int: The rounded integer.
    """
    # Extract the fractional part of the number
    fractional_part = n - int(n)

    # Check if the number is exactly halfway between two integers
    if abs(fractional_part) == 0.5:
        # If the integer part is even, round down; if odd, round up
        if int(n) % 2 == 0:
            return int(n)
        else:
            return int(n) + 1 if n > 0 else int(n) - 1
    else:
        # Use the built-in round function for other cases
        return round(n)

