def _dictsum(dicts: list[dict[str, int]]) -> dict[str, int]:
    """
    Sum the values for each key across a list of dictionaries.

    Args:
        dicts (list[dict[str, int]]): A list of dictionaries containing integer values.

    Returns:
        dict[str, int]: A dictionary with summed values for each key.
    """
    result = {}
    for dictionary in dicts:
        for key, value in dictionary.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result


