def make_find_paths(paths):
    """Converts a sequence of file paths into glob patterns.

    Args:
        paths (Sequence[str]): A sequence of file paths or glob patterns.

    Returns:
        Tuple[str]: A tuple of transformed paths as glob patterns.
    """
    def is_glob_pattern(path):
        """Determines whether a path is a glob pattern."""
        return '*' in path or '?' in path or '[' in path

    def convert_to_glob_pattern(path):
        """Converts a file path into a glob pattern."""
        return path.replace('/', '/**/').replace('\\', '\\**\\')

    transformed_paths = [
        path if is_glob_pattern(path) else convert_to_glob_pattern(path)
        for path in paths
    ]
    return tuple(transformed_paths)

