import re
from typing import Union

def get_pattern(pattern: Union[str, re.Pattern], strip: bool = True) -> re.Pattern:
    """
    Returns a compiled regex pattern object from the provided pattern.

    Args:
        pattern (Union[str, re.Pattern]): The pattern to compile into a regex pattern object.
        strip (bool): Whether to strip leading and trailing spaces from the pattern before compiling. Default is True.

    Returns:
        re.Pattern: The compiled regex pattern object.

    Raises:
        re.error: If the pattern is invalid and cannot be compiled into a regex pattern object.
    """
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as e:
            raise ValueError(f"Invalid regex pattern: {pattern}") from e
    elif isinstance(pattern, re.Pattern):
        return pattern
    else:
        raise TypeError("Pattern must be either a string or a regex pattern object.")
